package vn.svframe.svframelib.api.crafting.recipes.vmp; import vn.svframe.svframelib.api.crafting.recipes.MythicRecipeStation; import java.util.*; public class WorkbenchMapping extends VanillaInventoryMapping { public int getMainWidth(int r){return 3;} public int getMainHeight(int c){return 3;} public int getMainSlot(int x,int y){if(x<0||x>=3||y<0||y>=3)throw outOfBounds(x,y);return 1+y*3+x;} public int getMainInventoryStart(){return 1;} public int getMainInventoryWidth(){return 3;} public int getMainInventoryHeight(){return 3;} public int getResultWidth(int r){return 1;} public int getResultHeight(int c){return 1;} public int getResultSlot(int x,int y){if(x!=0||y!=0)throw outOfBounds(x,y);return 0;} public int getResultInventoryStart(){return 0;} public int getResultInventoryWidth(){return 1;} public int getResultInventoryHeight(){return 1;} public boolean isResultSlot(int s){return s==0;} public int getSideWidth(String n,int r){throw sideInventoryException(n);} public int getSideHeight(String n,int c){throw sideInventoryException(n);} public int getSideSlot(String n,int x,int y){throw sideInventoryException(n);} public int getSideInventoryStart(String n){throw sideInventoryException(n);} public int getSideInventoryWidth(String n){throw sideInventoryException(n);} public int getSideInventoryHeight(String n){throw sideInventoryException(n);} public boolean mainIsResult(){return false;} public MythicRecipeStation getIntendedStation(){return MythicRecipeStation.WORKBENCH;} public String getIntendedInventory(){return "CRAFTING_TABLE";} public ArrayList<String> getSideInventoryNames(){return new ArrayList<>();} }
